const result = [];
for (const item of $input.all()) {
  const email = item.json;
  const cats = Array.isArray(email.categories) ? email.categories : [];
  if (cats.includes('QUOTATION - PROCESSED')) continue;

  const from = (email.from && email.from.emailAddress)
    ? email.from.emailAddress.address
    : (email.from || '');

  const rawBody = (email.body && email.body.content)
    ? email.body.content
    : (email.bodyPreview || '');
  const cleanBody = rawBody.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

  const quoteMatch = /AECQ\d{8}/i.exec(email.subject || '');
  const quoteNumber = quoteMatch ? quoteMatch[0].toUpperCase() : null;

  result.push({ json: { messageId: email.id, from, subject: email.subject || '', cleanBody, quoteNumber } });
}
return result;

const email = $input.item.json;

const payload = {
  contents: [{
    role: 'user',
    parts: [{
      text: 'Extract air freight rates from this airline rate email. If the rate is described as "all-in", set isAllIn to true and set fuelSurchargePerKg and securitySurchargePerKg to 0. If a field is not mentioned, return 0 for numbers and empty string for transitTime.\n\nEmail:\n\n' + email.cleanBody
    }]
  }],
  generationConfig: {
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'object',
      properties: {
        airFreightRatePerKg:    { type: 'number' },
        isAllIn:                { type: 'boolean' },
        fuelSurchargePerKg:     { type: 'number' },
        securitySurchargePerKg: { type: 'number' },
        screeningFeePerKg:      { type: 'number' },
        transitTime:            { type: 'string' }
      },
      required: ['airFreightRatePerKg','isAllIn','fuelSurchargePerKg','securitySurchargePerKg','screeningFeePerKg','transitTime']
    }
  }
};

return { json: { ...email, geminiPayload: payload } };

function col(row, name) {
  const t = name.trim().toUpperCase();
  for (const [k, v] of Object.entries(row)) {
    if (k.trim().toUpperCase() === t) return v == null ? '' : String(v).trim();
  }
  return '';
}

const metadata = $('Get Sheet Metadata').first().json;
const sheets = metadata.sheets || [];
let templateSheetId = null, quotationSheetId = null;
for (const s of sheets) {
  const title = (s.properties && s.properties.title) || '';
  if (title === 'TEMPLATE') templateSheetId = s.properties.sheetId;
  if (title === 'QUOTATION') quotationSheetId = s.properties.sheetId;
}

const rowData = $('Get Quotation Rows').first().json;
const existingRows = (rowData.values || []).length;
let startRow = existingRows > 0 ? existingRows + 2 : 1;

const markupRows = $('Read Markup Config').all().map(i => i.json);
const minChargeRow = markupRows.find(r => col(r,'WEIGHT BREAK').toUpperCase() === 'MIN CHARGE');
const minCharge = minChargeRow ? (parseFloat(col(minChargeRow,'MARKUP')) || 175) : 175;
const breaks = markupRows
  .filter(r => !isNaN(parseFloat(col(r,'WEIGHT BREAK'))))
  .map(r => ({ wt: parseFloat(col(r,'WEIGHT BREAK')), markup: parseFloat(col(r,'MARKUP')) }))
  .sort((a,b) => a.wt - b.wt);

function getMarkupRate(cw) {
  const billable = Math.max(45, cw);
  let rate = breaks.length > 0 ? breaks[0].markup : 2.15;
  for (const b of breaks) { if (billable >= b.wt) rate = b.markup; }
  return (rate * billable) < minCharge ? minCharge / billable : rate;
}

const logRows = $('Read Quote Log').all().map(i => i.json);
const emailItems = $('Build Gemini Rate Payload').all();
const geminiItems = $input.all();
const result = [];

for (let i = 0; i < geminiItems.length; i++) {
  const gemini = geminiItems[i].json;
  const emailData = emailItems[i] ? emailItems[i].json : {};

  const rawText = gemini?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  let rates = { airFreightRatePerKg:0, isAllIn:false, fuelSurchargePerKg:0, securitySurchargePerKg:0, screeningFeePerKg:0, transitTime:'' };
  try {
    const cleaned = rawText.replace(/^```json\s*/i,'').replace(/```\s*$/i,'').trim();
    rates = { ...rates, ...JSON.parse(cleaned) };
  } catch(e) {}

  const quoteNumber = emailData.quoteNumber || '';
  const messageId = emailData.messageId || '';
  const logRow = logRows.find(r => col(r,'QUOTE NUMBER').trim() === quoteNumber.trim()) || {};

  const pod = col(logRow,'DEST') || col(logRow,'POD') || '';
  const cw = parseFloat(col(logRow,'CW (KGS)')) || 0;
  const airlineCode = col(logRow,'AIRLINE').split(',')[0].trim();
  const l = col(logRow,'L') || col(logRow,'LENGTH') || '';
  const w = col(logRow,'W') || col(logRow,'WIDTH') || '';
  const h = col(logRow,'H') || col(logRow,'HEIGHT') || '';
  const pcs = col(logRow,'PCS') || col(logRow,'PIECES') || '';
  const grossWeight = col(logRow,'GROSS WEIGHT') || col(logRow,'GW') || '';

  const billableCW = Math.max(45, cw);
  const netRate = parseFloat(rates.airFreightRatePerKg) || 0;
  const markupRate = getMarkupRate(cw);
  const sellingAirFreight = Math.round((netRate + markupRate) * 100) / 100;

  const fuelRate = rates.isAllIn ? 0 : (parseFloat(rates.fuelSurchargePerKg) || 0);
  const secRate  = rates.isAllIn ? 0 : (parseFloat(rates.securitySurchargePerKg) || 0);
  const screenRate = parseFloat(rates.screeningFeePerKg) || 0;
  const transitTime = String(rates.transitTime || '');

  const pol = 'ORD';
  const route = pod ? `ORD - ${pod}` : 'ORD -';

  const headerBlock = [
    'ESTIMATED COSTS (AIR GENERAL CARGO 1M1H Service)',
    `POL : ${pol}`,
    `POD : ${pod}`,
    `AIR CARRIER : ${airlineCode || 'UNASSIGNED'}`,
    `ROUTE : ${route}`,
    `TRANSIT TIME : ${transitTime} DAYS`
  ].join('\n');

  const footerBlock = [
    '* ABOVE RATE IS OUR NET SELLING RATE',
    '* INSURANCE CHARGE: CHICAGO CFS TO DESTINATION DOOR *if needed MIN $55.00 / $0.36/$100 by 110% of Invoice Value.'
  ].join('\n');

  result.push({ json: {
    startRow, templateSheetId, quotationSheetId,
    messageId, quoteNumber,
    l, w, h, pcs,
    grossWeightStr: grossWeight ? `${grossWeight} KGS` : '',
    cwStr: `${billableCW} KGS`,
    billableCW, headerBlock, footerBlock, sellingAirFreight,
    fuelRate,   fuelUnit:   fuelRate   > 0 ? billableCW : 0,
    secRate,    secUnit:    secRate    > 0 ? billableCW : 0,
    screenRate, screenUnit: screenRate > 0 ? billableCW : 0
  }});

  startRow += 19;
}

return result;

const d = $input.item.json;
const sr = d.startRow;

const copyBody = JSON.stringify({
  requests: [{
    copyPaste: {
      source:      { sheetId: d.templateSheetId, startRowIndex: 0,      endRowIndex: 19,          startColumnIndex: 0, endColumnIndex: 6 },
      destination: { sheetId: d.quotationSheetId, startRowIndex: sr - 1, endRowIndex: sr - 1 + 19, startColumnIndex: 0, endColumnIndex: 6 },
      pasteType: 'PASTE_NORMAL',
      pasteOrientation: 'NORMAL'
    }
  }]
});

const fillBody = JSON.stringify({
  valueInputOption: 'RAW',
  data: [
    { range: `QUOTATION!A${sr}`,               values: [[d.quoteNumber]] },
    { range: `QUOTATION!A${sr+3}:F${sr+3}`,    values: [[d.l, d.w, d.h, d.pcs, d.grossWeightStr, d.cwStr]] },
    { range: `QUOTATION!A${sr+5}`,              values: [[d.headerBlock]] },
    { range: `QUOTATION!B${sr+9}:C${sr+9}`,    values: [[d.sellingAirFreight, d.billableCW]] },
    { range: `QUOTATION!B${sr+10}:C${sr+10}`,  values: [[d.fuelRate, d.fuelUnit]] },
    { range: `QUOTATION!B${sr+11}:C${sr+11}`,  values: [[d.secRate, d.secUnit]] },
    { range: `QUOTATION!B${sr+12}:C${sr+12}`,  values: [[d.screenRate, d.screenUnit]] },
    { range: `QUOTATION!A${sr+17}`,             values: [[d.footerBlock]] }
  ]
});

return { json: { copyBody, fillBody } };
